{"thought": "Testing cascading promotion scenarios (rounding that pushes across multiple unit boundaries), extreme large magnitudes, exact power boundaries, and type errors, comparing impl against an independently written reference implementation of the spec.", "tool": "run_tests", "tests": [{"name": "test_cascading_promotion_and_large_values", "code": "import impl
import pytest
from decimal import Decimal


def ref_format(n, binary=False):
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError(f"n must be an int, not {type(n).__name__}")
    sign = '-' if n < 0 else ''
    m = abs(n)
    base = 1024 if binary else 1000
    units = ["B", "KiB", "MiB", "GiB", "TiB", "PiB"] if binary else ["B", "kB", "MB", "GB", "TB", "PB"]
    if m == 0:
        return "0 B"
    idx = 0
    for i in range(len(units) - 1, 0, -1):
        if m >= base ** i:
            idx = i
            break
    if idx == 0:
        return f"{sign}{m} B"
    while True:
        divisor = base ** idx
        num = m * 10
        q, r = divmod(num, divisor)
        if 2 * r >= divisor:
            q += 1
        if q >= base * 10 and idx < len(units) - 1:
            idx += 1
            continue
        break
    whole, frac = divmod(q, 10)
    return f"{sign}{whole}.{frac} {units[idx]}"


def test_cascading_promotion_and_large_values():
    cases = []
    for binary in (False, True):
        base = 1024 if binary else 1000
        for level in range(1, 6):
            divisor = base ** level
            boundary = divisor * base
            for delta in (-1, 0, 1, -(divisor // 20), (divisor // 20)):
                n = boundary + delta
                if n > 0:
                    cases.append((n, binary))
                    cases.append((-n, binary))
    for binary in (False, True):
        for n in (10**30, 2**100, -(10**30), -(2**100)):
            cases.append((n, binary))
    for binary in (False, True):
        base = 1024 if binary else 1000
        for level in range(0, 6):
            cases.append((base ** level, binary))

    for n, binary in cases:
        got = impl.format_bytes(n, binary=binary)
        want = ref_format(n, binary=binary)
        assert got == want, f"n={n} binary={binary}: got {got!r} want {want!r}"

    for bad in (1000.0, "1000", None, True, False, Decimal(1000)):
        with pytest.raises(TypeError):
            impl.format_bytes(bad)
